contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        c.fallback{value: amount}();

        address owner = c.owner();
        uint cBalBefore = address(c).balance;
        uint ownerBalBefore = owner.balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            !reverted &&
            address(c).balance == 0 &&
            owner.balance == ownerBalBefore + cBalBefore
        );
    }

    receive() external payable {}
}

