    function run(uint _value) public payable {
        // Fund c so it has a balance to withdraw from.
        // msg.sender of c is this InvMutTest contract, which is c's owner.
        uint depositAmount = _value + 1;
        require(address(this).balance >= depositAmount);
        c.fallback{value: depositAmount}();

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        if (_value <= balBefore) {
            assert(!reverted);
            assert(balAfter == balBefore - _value);
        } else {
            assert(reverted);
            assert(balAfter == balBefore);
        }
        assert(depositsAfter == depositsBefore);
    }

    receive() external payable {}
}

