    constructor(C _c) { c = _c; }

    function run(uint _value) public payable {
        uint depositAmount = _value + 1;
        require(address(this).balance >= depositAmount);
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent);

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        if (_value <= balBefore) {
            assert(!reverted);
            assert(balAfter == balBefore - _value);
        } else {
            assert(reverted);
            assert(balAfter == balBefore);
        }
        assert(depositsAfter == depositsBefore);
    }

    receive() external payable {}
}

