contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint value) public payable {
        // fund this test contract so it can attempt to send extra Ether to c if needed
        require(address(this).balance >= value, "need enough balance to cover value");

        // make c's balance strictly less than value by sending only value-1 to c (if value > 0)
        // then sendMoney(target, value) must fail because value > c.balance
        if (value > 0) {
            c.sendMoney(address(this), value - 1);
        }

        uint beforeBal = address(c).balance;

        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = address(c).balance;

        assert(reverted && afterBal == beforeBal);
    }

    receive() external payable {}
}

